export const languageNames={de:{de:'Deutsch',es:'Spanisch','pt-BR':'Portugiesisch (Brasilien)'},es:{de:'alemán',es:'español','pt-BR':'portugués de Brasil'},'pt-BR':{de:'alemão',es:'espanhol','pt-BR':'português do Brasil'}};
export function translator(locale='de'){
  const index={de:0,es:1,'pt-BR':2}[locale]??0;
  return (key,vars={})=>{
    if(!messages[key])throw Error('Missing UI message: '+key);
    return messages[key][index].replace(/\{(\w+)\}/g,(_,name)=>String(vars[name]??''));
  };
}

